  for (final locale in const [Locale('en'), Locale('ar')]) {
    for (final scale in [1.0, 2.0, 3.0]) {
      testWidgets('inbox preserves badge and tap at 320px ${locale.languageCode} scale=$scale', (tester) async {
        tester.view.physicalSize = const Size(320, 568);
        tester.view.devicePixelRatio = 1;
        addTearDown(tester.view.resetPhysicalSize);
        addTearDown(tester.view.resetDevicePixelRatio);
        final repo = _LargeInboxRepository();
        final attention = CommunityAttentionController(() async => const CommunityAttention(
          unreadMessages: 125, unreadBySender: {_LargeInboxRepository.peer: 125}));
        attention.setOwner(_LargeInboxRepository.owner);
        await attention.refresh();
        final router = GoRouter(routes: [
          GoRoute(path: '/', builder: (_, _) => CommunityMessagesPage(repository: repo)),
          GoRoute(path: '/community/chat/:userId', builder: (_, state) =>
            Scaffold(body: Text('opened:${state.pathParameters['userId']}'))),
        ]);
        addTearDown(attention.dispose);
        addTearDown(router.dispose);
        await tester.pumpWidget(MaterialApp.router(
          routerConfig: router,
          locale: locale,
          supportedLocales: AppLocalizations.supportedLocales,
          localizationsDelegates: const [AppLocalizations.delegate,
            GlobalMaterialLocalizations.delegate, GlobalWidgetsLocalizations.delegate,
            GlobalCupertinoLocalizations.delegate],
          builder: (context, child) => MediaQuery(
            data: MediaQuery.of(context).copyWith(textScaler: TextScaler.linear(scale)),
            child: CommunityAttentionScope(controller: attention,
              child: CommunitySurface(child: child!))),
        ));
        await tester.pumpAndSettle();
        final tile = find.byKey(const ValueKey('community-inbox-message-1'));
        expect(tile, findsOneWidget);
        expect(find.descendant(of: tile, matching: find.text('99+')), findsOneWidget);
        expect(attention.value.unreadMessages, 125, reason: 'Opening the inbox never marks messages read');
        expect(tester.takeException(), isNull);
        await tester.ensureVisible(tile);
        await tester.tap(tile);
        await tester.pumpAndSettle();
        expect(find.text('opened:${_LargeInboxRepository.peer}'), findsOneWidget);
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
      });
    }
  }


